function appendToDisplay(d){display.value+=d}function clearDisplay(){display.value=""}function calculate(){try{display.value=eval(display.value)}catch(l){display.value="Error"}}function calculateSquareRoot(){try{display.value=Math.sqrt(eval(display.value))}catch(l){display.value="Error"}}function calculateSquare(){try{display.value=Math.pow(eval(display.value),2)}catch(l){display.value="Error"}}